alter table public.profit_distribution_allocations
 add column if not exists investor_reference_snapshot text,
 add column if not exists investor_legal_name_snapshot text,
 add column if not exists bank_name_snapshot text,
 add column if not exists bank_account_name_snapshot text,
 add column if not exists bank_account_number_snapshot text,
 add column if not exists payout_snapshot_at timestamptz;
update public.profit_distribution_allocations a set investor_reference_snapshot=i.reference_code,investor_legal_name_snapshot=i.legal_name,bank_name_snapshot=i.bank_name,bank_account_name_snapshot=i.bank_account_name,bank_account_number_snapshot=i.bank_account_number,payout_snapshot_at=coalesce(a.updated_at,a.created_at,now()) from public.investors i where i.id=a.investor_id and a.status in ('payable','paid') and a.payout_snapshot_at is null;
create or replace function app.guard_profit_distribution_allocation_payout_snapshot() returns trigger language plpgsql security definer set search_path='' as $$begin if old.payout_snapshot_at is not null and (new.investor_reference_snapshot is distinct from old.investor_reference_snapshot or new.investor_legal_name_snapshot is distinct from old.investor_legal_name_snapshot or new.bank_name_snapshot is distinct from old.bank_name_snapshot or new.bank_account_name_snapshot is distinct from old.bank_account_name_snapshot or new.bank_account_number_snapshot is distinct from old.bank_account_number_snapshot or new.payout_snapshot_at is distinct from old.payout_snapshot_at) then raise exception 'Investor payout identity/bank snapshot is immutable.' using errcode='42501';end if;return new;end$$;
drop trigger if exists profit_distribution_allocation_payout_snapshot_guard on public.profit_distribution_allocations;
create trigger profit_distribution_allocation_payout_snapshot_guard before update on public.profit_distribution_allocations for each row execute function app.guard_profit_distribution_allocation_payout_snapshot();
revoke execute on function app.guard_profit_distribution_allocation_payout_snapshot() from public,anon,authenticated;
create or replace function app.transition_profit_distribution(p_distribution_id uuid,p_target public.profit_distribution_status) returns public.profit_distributions language plpgsql security definer set search_path='' as $$declare v_row public.profit_distributions%rowtype;v_required text;v_now timestamptz:=now();v_missing bigint;begin select * into v_row from public.profit_distributions where id=p_distribution_id for update;if v_row.id is null then raise exception 'Distribution not found.' using errcode='P0002';end if;if v_row.status='draft' and p_target='review' then v_required:='profit_distributions.update';elsif v_row.status='review' and p_target='approved' then v_required:='profit_distributions.approve';elsif v_row.status='approved' and p_target='payable' then v_required:='profit_distributions.publish';else raise exception 'Invalid distribution transition: % -> %',v_row.status,p_target using errcode='42501';end if;if not app.has_permission(v_required) then raise exception 'Missing permission: %',v_required using errcode='42501';end if;if p_target='approved' and v_row.created_by=auth.uid() then raise exception 'Pembuat distribusi tidak dapat menyetujui distribusi yang sama.' using errcode='42501';end if;if p_target='payable' and v_row.approved_by=auth.uid() then raise exception 'Penyetuju distribusi tidak dapat menerbitkan distribusi yang sama menjadi payable.' using errcode='42501';end if;perform app.assert_profit_distribution_allocations(v_row.id);if p_target='review' and v_row.investor_pool_amount>0 and not exists(select 1 from public.profit_distribution_allocations where distribution_id=v_row.id and status='pending') then raise exception 'Investor allocations must be generated before review.' using errcode='23514';end if;if p_target='payable' then if v_row.investor_pool_amount>0 and not exists(select 1 from public.profit_distribution_allocations where distribution_id=v_row.id and status='pending') then raise exception 'Pending investor allocations are required before publication.' using errcode='23514';end if;select count(*) into v_missing from public.profit_distribution_allocations a join public.investors i on i.id=a.investor_id where a.distribution_id=v_row.id and a.status='pending' and (nullif(btrim(coalesce(i.reference_code,'')),'') is null or nullif(btrim(coalesce(i.legal_name,'')),'') is null or nullif(btrim(coalesce(i.bank_name,'')),'') is null or nullif(btrim(coalesce(i.bank_account_name,'')),'') is null or nullif(btrim(coalesce(i.bank_account_number,'')),'') is null);if v_missing>0 then raise exception '% investor allocation(s) do not have complete identity/bank details for payout.',v_missing using errcode='23514';end if;update public.profit_distribution_allocations a set status='payable',investor_reference_snapshot=i.reference_code,investor_legal_name_snapshot=i.legal_name,bank_name_snapshot=i.bank_name,bank_account_name_snapshot=i.bank_account_name,bank_account_number_snapshot=i.bank_account_number,payout_snapshot_at=v_now,updated_at=v_now from public.investors i where a.distribution_id=v_row.id and a.status='pending' and i.id=a.investor_id;end if;update public.profit_distributions set status=p_target,approved_at=case when p_target='approved' then v_now else approved_at end,approved_by=case when p_target='approved' then auth.uid() else approved_by end,payable_at=case when p_target='payable' then v_now else payable_at end,payable_by=case when p_target='payable' then auth.uid() else payable_by end,updated_by=auth.uid() where id=v_row.id returning * into v_row;insert into public.audit_logs(actor_user_id,actor_type,action,entity_type,entity_id,summary,changes) values(auth.uid(),app.current_actor_type(),'profit_distribution.'||p_target::text,'profit_distribution',v_row.id,'Status distribusi laba diperbarui.',jsonb_build_object('status',p_target));return v_row;end$$;